CREATE OR REPLACE FUNCTION public.generate_quote_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE year_short text; max_num integer; new_number text;
BEGIN
  -- Só calcula/gera se o número ainda não foi informado.
  IF NEW.quote_number IS NOT NULL AND NEW.quote_number <> '' THEN
    RETURN NEW;
  END IF;

  year_short := to_char(now(), 'YY');

  -- Serializa a geração por ano (transaction-scoped: liberado no commit/rollback).
  PERFORM pg_advisory_xact_lock(hashtext('quote_number:' || year_short)::bigint);

  -- ANTI-REGRESSAO (20260626_quote_number_int4_guard): '^\d{1,9}$' (NAO '^\d+$')
  -- evita overflow de int4 caso um prefixo malformado com 10+ digitos exista.
  SELECT COALESCE(MAX(
    CASE WHEN split_part(quote_number, '/', 1) ~ '^\d{1,9}$'
         THEN split_part(quote_number, '/', 1)::integer ELSE 0 END
  ), 10000) INTO max_num
  FROM public.quotes WHERE quote_number LIKE '%/' || year_short;

  new_number := (max_num + 1)::text || '/' || year_short;
  NEW.quote_number := new_number;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_quote_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  notif_title TEXT;
  notif_message TEXT;
  notif_type TEXT;
  notif_category TEXT := 'quotes';
  notif_url TEXT := '/orcamentos';
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;

  CASE NEW.status
    WHEN 'approved' THEN
      notif_title   := '✅ Orçamento aprovado!';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi aprovado!';
      notif_type    := 'success';
    WHEN 'rejected' THEN
      notif_title   := '❌ Orçamento recusado';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi recusado.';
      notif_type    := 'warning';
    WHEN 'sent' THEN
      notif_title   := '📤 Orçamento enviado';
      notif_message := 'O orçamento ' || NEW.quote_number || ' foi marcado como enviado.';
      notif_type    := 'info';
    WHEN 'expired' THEN
      notif_title   := '⏰ Orçamento expirado';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' expirou.';
      notif_type    := 'warning';
    WHEN 'pending_approval' THEN
      notif_title   := '⏳ Orçamento aguardando aprovação';
      notif_message := 'O orçamento ' || NEW.quote_number || ' foi submetido para aprovação de desconto.';
      notif_type    := 'info';
    WHEN 'converted' THEN
      notif_title   := '🎉 Orçamento convertido em pedido!';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi convertido em pedido.';
      notif_type    := 'success';
      notif_url     := '/pedidos';
    WHEN 'cancelled' THEN
      notif_title   := '🚫 Orçamento cancelado';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi cancelado.';
      notif_type    := 'warning';
    ELSE
      RETURN NEW;
  END CASE;

  IF NEW.seller_id IS NOT NULL THEN
    INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url)
    VALUES (NEW.seller_id, notif_title, notif_message, notif_type, notif_category, notif_url);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_quote_children_enforce_parent_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _parent_quote_id uuid;
  _parent_status text;
  _msg text;
BEGIN
  -- fix_version=2026-07-09-quote-children-immutability-bypass ANTI-REGRESSÃO
  -- Bypass para service_role via JWT claim (PostgREST com JWT token)
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- NOVO: Bypass para contexto sem usuário autenticado (service_role sem JWT,
  -- edge functions com service_role_key, execute_sql, migrations, crons).
  IF auth.uid() IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_TABLE_NAME = 'quote_items' THEN
    _parent_quote_id := COALESCE(NEW.quote_id, OLD.quote_id);
  ELSIF TG_TABLE_NAME = 'quote_item_personalizations' THEN
    SELECT qi.quote_id INTO _parent_quote_id
    FROM public.quote_items qi
    WHERE qi.id = COALESCE(NEW.quote_item_id, OLD.quote_item_id);
  END IF;

  IF _parent_quote_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT status INTO _parent_status
  FROM public.quotes WHERE id = _parent_quote_id;

  IF _parent_status IN ('approved', 'converted') THEN
    _msg := 'Nao e possivel alterar itens de orcamento ja aprovado/convertido (status ' ||
            _parent_status || '). Crie um novo orcamento.';
    RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_qip_propagate_to_quote_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _quote_item_id uuid;
  _new_personalization_cost numeric(12,2);
BEGIN
  _quote_item_id := COALESCE(NEW.quote_item_id, OLD.quote_item_id);

  SELECT COALESCE(SUM(total_cost), 0) INTO _new_personalization_cost
  FROM public.quote_item_personalizations
  WHERE quote_item_id = _quote_item_id;

  UPDATE public.quote_items 
  SET personalization_cost = _new_personalization_cost,
      has_personalization = (_new_personalization_cost > 0),
      updated_at = now()
  WHERE id = _quote_item_id
    AND personalization_cost IS DISTINCT FROM _new_personalization_cost;

  RETURN COALESCE(NEW, OLD);
END;
$function$

