CREATE OR REPLACE FUNCTION public.fn_quotes_enforce_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _msg text;
BEGIN
  -- fix_version=2026-07-09-immutability-service-role-bypass ANTI-REGRESSÃO
  -- Bypass para service_role via JWT claim (PostgREST com JWT token)
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  -- NOVO: Bypass para contexto sem usuário autenticado (service_role sem JWT,
  -- edge functions com service_role_key, execute_sql, migrations, crons).
  -- auth.uid() IS NULL = indicador robusto de service_role sem JWT.
  -- O bypass request.jwt.claim.role acima falha quando NULL (NULL='service_role'→FALSE).
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF OLD.status NOT IN ('approved', 'converted') THEN
    RETURN NEW;
  END IF;

  IF OLD.* IS NOT DISTINCT FROM NEW.* THEN
    RETURN NEW;
  END IF;

  IF OLD.status <> NEW.status THEN
    IF (OLD.status = 'approved' AND NEW.status IN ('converted', 'expired'))
       OR (OLD.status = 'converted' AND NEW.status = 'expired') THEN
      IF (
        OLD.client_id IS DISTINCT FROM NEW.client_id OR
        OLD.client_name IS DISTINCT FROM NEW.client_name OR
        OLD.subtotal IS DISTINCT FROM NEW.subtotal OR
        OLD.discount_percent IS DISTINCT FROM NEW.discount_percent OR
        OLD.discount_amount IS DISTINCT FROM NEW.discount_amount OR
        OLD.total IS DISTINCT FROM NEW.total OR
        OLD.negotiation_markup_percent IS DISTINCT FROM NEW.negotiation_markup_percent OR
        OLD.real_subtotal IS DISTINCT FROM NEW.real_subtotal OR
        OLD.real_discount_percent IS DISTINCT FROM NEW.real_discount_percent OR
        OLD.shipping_cost IS DISTINCT FROM NEW.shipping_cost OR
        OLD.tax_amount IS DISTINCT FROM NEW.tax_amount OR
        OLD.seller_id IS DISTINCT FROM NEW.seller_id OR
        OLD.created_by IS DISTINCT FROM NEW.created_by OR
        OLD.assigned_to IS DISTINCT FROM NEW.assigned_to
      ) THEN
        _msg := 'Orcamento em status ' || OLD.status ||
                ' e imutavel. So a transicao de status e permitida; valores e atribuicoes nao podem mudar. Crie um novo orcamento.';
        RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    ELSE
      _msg := 'Transicao de status nao permitida: ' || OLD.status || ' para ' || NEW.status ||
              '. Orcamento em status ' || OLD.status || ' so pode ir para converted ou expired.';
      RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
    END IF;
  END IF;

  _msg := 'Orcamento em status ' || OLD.status ||
          ' e imutavel. Crie um novo orcamento para alterar valores.';
  RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notify_champions_on_quote_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'vault', 'net'
AS $function$
-- fix_version=2026-07-10-notify-champions-v8-clock-timestamp ANTI-REGRESSÃO
-- v8: event_at usa clock_timestamp() — NOW() era transaction_timestamp e gerava
-- timestamps idênticos para múltiplas transições na mesma transação,
-- quebrando o ordering guard do Champions.
DECLARE
  _secret  TEXT;
  _url     TEXT;
  _payload JSONB;
  _hmac    TEXT;
  _req_id  BIGINT;
  _log_id  UUID;
  _start   TIMESTAMPTZ;
  _ck      TEXT;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;

  _start := clock_timestamp();
  _ck := NEW.id::text || ':' || NEW.status || ':' || (extract(epoch from clock_timestamp()) * 1000)::bigint::text;

  BEGIN
    SELECT ds.decrypted_secret INTO _url
    FROM vault.decrypted_secrets ds WHERE ds.name = 'CHAMPIONS_RECEIVE_QUOTE_SYNC_URL' LIMIT 1;
    SELECT ds.decrypted_secret INTO _secret
    FROM vault.decrypted_secrets ds WHERE ds.name = 'WEBHOOK_DISPATCHER_SECRET' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_notify_champions v8: vault error: %', SQLERRM;
    RETURN NEW;
  END;

  IF _url IS NULL OR _secret IS NULL THEN
    RAISE WARNING 'fn_notify_champions v8: URL ou secret NULL';
    RETURN NEW;
  END IF;

  _payload := json_build_object(
    'event',           'quote.' || NEW.status,
    'correlation_key', _ck,
    'payload', json_build_object(
      'quote_id',     NEW.id,
      'quote_number', NEW.quote_number,
      'status',       NEW.status,
      'old_status',   OLD.status,
      'seller_id',    NEW.seller_id,
      'client_id',    NEW.client_id,
      'client_name',  NEW.client_name,
      'total',        NEW.total,
      'event_at',     clock_timestamp()   -- ← v8 FIX: monotônico intra-transação
    )
  )::jsonb;

  _hmac := 'sha256=' || encode(
    extensions.hmac(_payload::text::bytea, _secret::bytea, 'sha256'), 'hex');

  BEGIN
    INSERT INTO public.webhook_dispatcher_log (
      trigger_event, quote_id, quote_status, seller_id,
      target_url, correlation_key, payload_hash, delivery_status, fired_at
    ) VALUES (
      'quote.' || NEW.status, NEW.id, NEW.status, NEW.seller_id,
      regexp_replace(_url, 'https://[^/]+\.supabase\.co', 'https://[REDACTED].supabase.co'),
      _ck,
      encode(extensions.hmac(_payload::text::bytea, 'log-salt'::bytea, 'sha256'), 'hex'),
      'pending', _start
    ) RETURNING id INTO _log_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_notify_champions v8: pre-log error: %', SQLERRM;
  END;

  BEGIN
    SELECT net.http_post(
      _url, _payload, '{}'::jsonb,
      json_build_object(
        'Content-Type',        'application/json',
        'x-webhook-signature', _hmac,
        'x-webhook-event',     'quote.' || NEW.status,
        'x-correlation-key',   _ck
      )::jsonb,
      10000
    ) INTO _req_id;

    IF _log_id IS NOT NULL THEN
      UPDATE public.webhook_dispatcher_log
      SET response_body = 'pg_net_request_id=' || _req_id::text,
          delivery_status = 'delivered',
          responded_at = clock_timestamp(),
          duration_ms = EXTRACT(EPOCH FROM (clock_timestamp() - _start)) * 1000
      WHERE id = _log_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_notify_champions v8: http_post error quote %: %', NEW.id, SQLERRM;
    IF _log_id IS NOT NULL THEN
      BEGIN
        UPDATE public.webhook_dispatcher_log
        SET delivery_status = 'failed', error_message = SQLERRM,
            responded_at = clock_timestamp(),
            duration_ms = EXTRACT(EPOCH FROM (clock_timestamp() - _start)) * 1000
        WHERE id = _log_id;
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
  END;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_notify_champions v8: outer error quote %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_quotes_recalc_subtotal_from_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _quote_id uuid;
  _quote_status text;
  _markup numeric;
  _disc_amount_db numeric;
  _disc_pct numeric;
  _ship_type text;
  _ship_cost numeric;
  _real_subtotal numeric(12,2);
  _new_subtotal numeric(12,2);
  _ship_value numeric(12,2);
  _disc_value numeric(12,2);
  _new_total numeric(12,2);
BEGIN
  _quote_id := COALESCE(NEW.quote_id, OLD.quote_id);
  IF _quote_id IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;

  SELECT
    status,
    LEAST(50, GREATEST(0, COALESCE(negotiation_markup_percent, 0))),
    COALESCE(discount_amount, 0),
    COALESCE(discount_percent, 0),
    shipping_type,
    COALESCE(shipping_cost, 0)
  INTO _quote_status, _markup, _disc_amount_db, _disc_pct, _ship_type, _ship_cost
  FROM public.quotes WHERE id = _quote_id;

  -- Nao mexer em quotes aprovados/convertidos (imutaveis)
  IF _quote_status IN ('approved', 'converted') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- REAL: soma pura dos itens (sem markup)
  SELECT COALESCE(SUM(quantity * unit_price + COALESCE(personalization_cost, 0)), 0)
  INTO _real_subtotal
  FROM public.quote_items
  WHERE quote_id = _quote_id;

  -- APRESENTADO ao cliente: aplica markup
  _new_subtotal := ROUND(_real_subtotal * (1 + _markup / 100.0), 2);

  -- DESCONTO: discount_percent tem prioridade (espelha logica do frontend)
  IF _disc_pct > 0 THEN
    _disc_value := ROUND(_new_subtotal * (_disc_pct / 100.0), 2);
  ELSE
    _disc_value := _disc_amount_db;
  END IF;

  -- FRETE: somente 'fob_pre' (pré-negociado com custo) entra no total.
  -- Alinhado ao frontend (calculateQuoteTotals): cif/fob/null não somam.
  _ship_value := CASE WHEN _ship_type = 'fob_pre' THEN _ship_cost ELSE 0 END;

  -- TOTAL final
  _new_total := _new_subtotal - _disc_value + _ship_value;

  -- UPDATE apenas se mudou (evita loop com trigger BEFORE em quotes)
  UPDATE public.quotes
  SET subtotal = _new_subtotal,
      total = _new_total,
      discount_amount = _disc_value,
      updated_at = now()
  WHERE id = _quote_id
    AND (subtotal IS DISTINCT FROM _new_subtotal
      OR total IS DISTINCT FROM _new_total
      OR discount_amount IS DISTINCT FROM _disc_value);

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_quotes_validate_discount()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _max_allowed numeric;
  _real_discount_pct numeric;
  _has_valid_approval boolean;
  _current_hash text;
  _seller_id uuid;
  _msg text;
  _decision_request_id uuid;
BEGIN
  IF NEW.status = 'expired' THEN RETURN NEW; END IF;
  IF current_setting('app.write_source', true) = 'cron_expire' THEN RETURN NEW; END IF;
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN RETURN NEW; END IF;
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;

  BEGIN
    _decision_request_id := NULLIF(
      current_setting('app.discount_approval_request_id', true), ''
    )::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    _decision_request_id := NULL;
  END;

  IF TG_OP = 'UPDATE'
     AND OLD.status = 'pending_approval' AND NEW.status = 'draft'
     AND _decision_request_id IS NOT NULL
     AND NEW.client_id IS NOT DISTINCT FROM OLD.client_id
     AND NEW.client_name IS NOT DISTINCT FROM OLD.client_name
     AND NEW.subtotal IS NOT DISTINCT FROM OLD.subtotal
     AND NEW.discount_percent IS NOT DISTINCT FROM OLD.discount_percent
     AND NEW.discount_amount IS NOT DISTINCT FROM OLD.discount_amount
     AND NEW.negotiation_markup_percent IS NOT DISTINCT FROM OLD.negotiation_markup_percent
     AND NEW.total IS NOT DISTINCT FROM OLD.total
     AND NEW.real_discount_percent IS NOT DISTINCT FROM OLD.real_discount_percent
     AND NEW.seller_id IS NOT DISTINCT FROM OLD.seller_id
     AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
     AND EXISTS (
       SELECT 1 FROM public.discount_approval_requests dar
       WHERE dar.id = _decision_request_id AND dar.quote_id = NEW.id
         AND dar.status = 'rejected' AND dar.admin_id = auth.uid()
         AND dar.quote_snapshot_hash = public.compute_quote_snapshot_hash(NEW.id)
     ) THEN
    RETURN NEW;
  END IF;

  _seller_id := COALESCE(NEW.seller_id, NEW.created_by);
  IF _seller_id IS NULL THEN RETURN NEW; END IF;
  IF public.is_supervisor_or_above(_seller_id) THEN RETURN NEW; END IF;

  _real_discount_pct := COALESCE(NEW.real_discount_percent, 0);
  IF _real_discount_pct <= 0 THEN RETURN NEW; END IF;

  SELECT max_discount_percent INTO _max_allowed
  FROM public.seller_discount_limits WHERE user_id = _seller_id;
  IF _max_allowed IS NULL THEN
    RAISE EXCEPTION 'Vendedor sem limite de desconto cadastrado. Solicite ao admin que configure seu limite antes de salvar orcamentos.'
      USING ERRCODE = '23514';
  END IF;
  IF _real_discount_pct <= _max_allowed THEN RETURN NEW; END IF;

  IF TG_OP = 'INSERT' THEN
    IF COALESCE(NEW.status, 'draft') = 'pending_approval' THEN RETURN NEW; END IF;
    _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
      ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
      ' por cento. Para solicitar aprovacao, use o botao "Solicitar aprovacao ao coordenador" que cria o orcamento em status pendente.';
    RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
  END IF;

  _current_hash := public.compute_quote_snapshot_hash(NEW.id);
  SELECT EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id AND status = 'approved'
      AND (valid_until IS NULL OR valid_until > now())
      AND requested_discount_percent >= _real_discount_pct
      AND quote_snapshot_hash = _current_hash
  ) INTO _has_valid_approval;
  IF _has_valid_approval THEN RETURN NEW; END IF;

  IF EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id AND status = 'approved'
      AND ((valid_until IS NOT NULL AND valid_until <= now())
        OR quote_snapshot_hash <> _current_hash)
  ) THEN
    RAISE EXCEPTION 'Aprovacao anterior nao vale mais (orcamento foi alterado ou aprovacao expirou). Solicite nova aprovacao ao coordenador.'
      USING ERRCODE = '23514';
  END IF;

  IF COALESCE(NEW.status, 'draft') = 'pending_approval' THEN RETURN NEW; END IF;
  _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
    ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
    ' por cento. Solicite aprovacao ao coordenador antes de salvar.';
  RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validate_selected_packaging()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.selected_packaging_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM products WHERE id=NEW.selected_packaging_id AND product_type='packaging' AND is_active) THEN
      RAISE EXCEPTION 'selected_packaging_id % nao referencia produto type=packaging ativo', NEW.selected_packaging_id;
    END IF;
  END IF;
  RETURN NEW;
END$function$
